module pc (
  input CLK,
  input \~SR ,
  input [23:0] ADDR_ABS,
  input [23:0] OFFSET,
  input [23:0] ADDR_RET,
  input MUX1_SEL,
  input MUX2_SEL,
  input FLAG_N,
  input FLAG_C,
  input FLAG_Z,
  input FLAG_O,
  input [2:0] COND,
  input BRANCH_EN,
  input INT_EN_IN,
  input HALT_IN,
  input INT_REQ,
  input INT_VEC_0,
  input INT_VEC_1,
  input INT_VEC_2,
  input [23:0] SP_DELTA,
  input SP_LOAD_N,
  input JUMP_UNCOND,
  input PCEN,
  output INT_EN,
  output HALTED,
  output [23:0] PC_OUT,
  output [23:0] SP_OUT,
  output INT_ACK,
  output [3:0] FLAGS_SAVE,
  output [23:0] PC_SAVE
);
  wire CLK_GATED;
  wire PC_LOAD_N;
  wire [23:0] LOAD_ADDR;
  wire [23:0] PC_OUT_temp;
  wire [23:0] SP_OUT_temp;
  wire [23:0] SP_D;
  wire COND_RESULT;
  wire [23:0] PC_REL;
  wire [23:0] INT_VECTOR;
  wire INT_ACK_temp;
  wire [23:0] \PC+1 ;
  wire [1:0] \mux-sel ;
  // SC4-1
  sc_branch sc_branch_i0 (
    .FLAG_N( FLAG_N ),
    .FLAG_C( FLAG_C ),
    .FLAG_Z( FLAG_Z ),
    .FLAG_O( FLAG_O ),
    .COND( COND ),
    .BRANCH_EN( BRANCH_EN ),
    .COND_RESULT( COND_RESULT )
  );
  // SC5-1
  sc_control_flags sc_control_flags_i1 (
    .INT_EN_IN( INT_EN_IN ),
    .HALT_IN( HALT_IN ),
    .INT_REQ( INT_REQ ),
    .INT_VEC_0( INT_VEC_0 ),
    .INT_VEC_1( INT_VEC_1 ),
    .INT_VEC_2( INT_VEC_2 ),
    .CLK( CLK ),
    .INT_VECTOR( INT_VECTOR ),
    .INT_EN( INT_EN ),
    .HALTED( HALTED ),
    .INT_GATE( INT_ACK_temp ),
    .CLK_GATED( CLK_GATED )
  );
  assign \PC+1 [0] = 1'b1;
  assign \PC+1 [1] = 1'b0;
  assign \PC+1 [2] = 1'b0;
  assign \PC+1 [3] = 1'b0;
  assign \PC+1 [4] = 1'b0;
  assign \PC+1 [5] = 1'b0;
  assign \PC+1 [6] = 1'b0;
  assign \PC+1 [7] = 1'b0;
  assign \PC+1 [8] = 1'b0;
  assign \PC+1 [9] = 1'b0;
  assign \PC+1 [10] = 1'b0;
  assign \PC+1 [11] = 1'b0;
  assign \PC+1 [12] = 1'b0;
  assign \PC+1 [13] = 1'b0;
  assign \PC+1 [14] = 1'b0;
  assign \PC+1 [15] = 1'b0;
  assign \PC+1 [16] = 1'b0;
  assign \PC+1 [17] = 1'b0;
  assign \PC+1 [18] = 1'b0;
  assign \PC+1 [19] = 1'b0;
  assign \PC+1 [20] = 1'b0;
  assign \PC+1 [21] = 1'b0;
  assign \PC+1 [22] = 1'b0;
  assign \PC+1 [23] = 1'b0;
  // SC6-1
  sc_flags_save sc_flags_save_i2 (
    .INT_GATE( INT_ACK_temp ),
    .FLAG_N( FLAG_N ),
    .FLAG_C( FLAG_C ),
    .FLAG_Z( FLAG_Z ),
    .FLAG_O( FLAG_O ),
    .FLAGS_SAVE( FLAGS_SAVE )
  );
  assign PC_LOAD_N = ~ (COND_RESULT | INT_ACK_temp | JUMP_UNCOND);
  assign \mux-sel [0] = (INT_ACK_temp | (~ MUX2_SEL & MUX1_SEL));
  assign \mux-sel [1] = (MUX2_SEL | INT_ACK_temp);
  // SC1-1
  sc_pc_counter sc_pc_counter_i3 (
    .\~SR ( \~SR  ),
    .clk( CLK_GATED ),
    .\~PE ( PC_LOAD_N ),
    .D( LOAD_ADDR ),
    .\pc-en ( PCEN ),
    .Q( PC_OUT_temp )
  );
  // SC2-2
  sc_adder24 sc_adder24_i4 (
    .B( SP_DELTA ),
    .A( SP_OUT_temp ),
    .S( SP_D )
  );
  // SC1-2
  sc_pc_counter sc_pc_counter_i5 (
    .\~SR ( \~SR  ),
    .clk( CLK_GATED ),
    .\~PE ( SP_LOAD_N ),
    .D( SP_D ),
    .\pc-en ( PCEN ),
    .Q( SP_OUT_temp )
  );
  // SC2-1
  sc_adder24 sc_adder24_i6 (
    .B( OFFSET ),
    .A( PC_OUT_temp ),
    .S( PC_REL )
  );
  // SC2-3
  sc_adder24 sc_adder24_i7 (
    .B( \PC+1  ),
    .A( PC_OUT_temp ),
    .S( PC_SAVE )
  );
  Mux_4x1_NBits #(
    .Bits(24)
  )
  Mux_4x1_NBits_i8 (
    .sel( \mux-sel  ),
    .in_0( ADDR_ABS ),
    .in_1( PC_REL ),
    .in_2( ADDR_RET ),
    .in_3( INT_VECTOR ),
    .out( LOAD_ADDR )
  );
  assign PC_OUT = PC_OUT_temp;
  assign SP_OUT = SP_OUT_temp;
  assign INT_ACK = INT_ACK_temp;
endmodule
module DIG_RAMDualAccess
#(
    parameter Bits = 8,
    parameter AddrBits = 4
)
(
    input C, // Clock signal
    input ld,
    input [(AddrBits-1):0] \1A ,
    input [(AddrBits-1):0] \2A ,
    input [(Bits-1):0] \1Din ,
    input str,
    output [(Bits-1):0] \1D ,
    output [(Bits-1):0] \2D
);
    // CAUTION: uses distributed RAM
    reg [(Bits-1):0] memory [0:((1 << AddrBits)-1)];

    assign \1D = ld? memory[\1A ] : 'hz;
    assign \2D = memory[\2A ];

    always @ (posedge C) begin
        if (str)
            memory[\1A ] <= \1Din ;
    end

endmodule



module register (
  input WE,
  input [31:0] DATA_W,
  input [7:0] ADDR_A,
  input [7:0] ADDR_B,
  input [7:0] ADDR_W,
  input EXEC,
  input addr_c_sel,
  input [31:0] ir_bus,
  input clk,
  output [31:0] DATA_A,
  output [31:0] DATA_B,
  output [31:0] DATA_C
);
  wire \ram-and ;
  wire [7:0] ADDR_C;
  wire [7:0] \0x00 ;
  wire [7:0] IR_ADDR_CIN;
  assign \ram-and  = (EXEC & WE);
  assign \0x00 [0] = 1'b0;
  assign \0x00 [1] = 1'b0;
  assign \0x00 [2] = 1'b0;
  assign \0x00 [3] = 1'b0;
  assign \0x00 [4] = 1'b0;
  assign \0x00 [5] = 1'b0;
  assign \0x00 [6] = 1'b0;
  assign \0x00 [7] = 1'b0;
  assign IR_ADDR_CIN = ir_bus[23:16];
  // U1
  DIG_RAMDualAccess #(
    .Bits(32),
    .AddrBits(8)
  )
  DIG_RAMDualAccess_i0 (
    .str( \ram-and  ),
    .C( clk ),
    .ld( 1'b1 ),
    .\1A ( ADDR_W ),
    .\1Din ( DATA_W ),
    .\2A ( ADDR_A ),
    .\2D ( DATA_A )
  );
  // U2
  DIG_RAMDualAccess #(
    .Bits(32),
    .AddrBits(8)
  )
  DIG_RAMDualAccess_i1 (
    .str( \ram-and  ),
    .C( clk ),
    .ld( 1'b1 ),
    .\1A ( ADDR_W ),
    .\1Din ( DATA_W ),
    .\2A ( ADDR_B ),
    .\2D ( DATA_B )
  );
  Mux_2x1_NBits #(
    .Bits(8)
  )
  Mux_2x1_NBits_i2 (
    .sel( addr_c_sel ),
    .in_0( \0x00  ),
    .in_1( IR_ADDR_CIN ),
    .out( ADDR_C )
  );
  // U3
  DIG_RAMDualAccess #(
    .Bits(32),
    .AddrBits(8)
  )
  DIG_RAMDualAccess_i3 (
    .str( \ram-and  ),
    .C( clk ),
    .ld( 1'b1 ),
    .\1A ( ADDR_W ),
    .\1Din ( DATA_W ),
    .\2A ( ADDR_C ),
    .\2D ( DATA_C )
  );
endmodule

module flag_reg (
  input ZERO_IN,
  input CARRY_IN,
  input NEGATIVE_IN,
  input OVERFLOW_IN,
  input FLAG_WE,
  input CLK,
  input EXEC,
  output FLAG_Z,
  output FLAG_C,
  output FLAG_N,
  output FLAG_O
);
  wire CLK_GATED;
  wire FLAG_Z_N;
  wire FLAG_C_N;
  wire FLAG_NN;
  wire FLAG_O_N;
  assign CLK_GATED = (CLK & EXEC & FLAG_WE);
  \7474  \7474_i0 (
    .\~1RD ( 1'b1 ),
    .\1D ( ZERO_IN ),
    .\1CP ( CLK_GATED ),
    .\~1SD ( 1'b1 ),
    .GND( 1'b0 ),
    .\~2SD ( 1'b1 ),
    .\2CP ( CLK_GATED ),
    .\2D ( CARRY_IN ),
    .\~2RD ( 1'b1 ),
    .VCC( 1'b1 ),
    .\1Q ( FLAG_Z ),
    .\~1Q ( FLAG_Z_N ),
    .\~2Q ( FLAG_C_N ),
    .\2Q ( FLAG_C )
  );
  \7474  \7474_i1 (
    .\~1RD ( 1'b1 ),
    .\1D ( NEGATIVE_IN ),
    .\1CP ( CLK_GATED ),
    .\~1SD ( 1'b1 ),
    .GND( 1'b0 ),
    .\~2SD ( 1'b1 ),
    .\2CP ( CLK_GATED ),
    .\2D ( OVERFLOW_IN ),
    .\~2RD ( 1'b1 ),
    .VCC( 1'b1 ),
    .\1Q ( FLAG_N ),
    .\~1Q ( FLAG_NN ),
    .\~2Q ( FLAG_O_N ),
    .\2Q ( FLAG_O )
  );
endmodule

