module CompUnsigned #(
    parameter Bits = 1
)
(
    input [(Bits -1):0] a,
    input [(Bits -1):0] b,
    output \> ,
    output \= ,
    output \<
);
    assign \> = a > b;
    assign \= = a == b;
    assign \< = a < b;
endmodule


module DriverInvBus#(
    parameter Bits = 2
)
(
    input [(Bits-1):0] in,
    input sel,
    output [(Bits-1):0] out
);
    assign out = (sel == 1'b0)? in : {Bits{1'bz}};
endmodule

module DriverBus#(
    parameter Bits = 2
)
(
    input [(Bits-1):0] in,
    input sel,
    output [(Bits-1):0] out
);
    assign out = (sel == 1'b1)? in : {Bits{1'bz}};
endmodule

module mmio_bus (
  input [23:0] ADDR,
  output [23:0] CPU_ADDR_OUT,
  output [23:0] mmio_addr,
  output is_mmio
);
  wire [3:0] s0;
  wire is_mmio_temp;
  assign s0 = ADDR[23:20];
  CompUnsigned #(
    .Bits(4)
  )
  CompUnsigned_i0 (
    .a( s0 ),
    .b( 4'b1111 ),
    .\= ( is_mmio_temp )
  );
  DriverInvBus #(
    .Bits(24)
  )
  DriverInvBus_i1 (
    .in( ADDR ),
    .sel( is_mmio_temp ),
    .out( CPU_ADDR_OUT )
  );
  DriverBus #(
    .Bits(24)
  )
  DriverBus_i2 (
    .in( ADDR ),
    .sel( is_mmio_temp ),
    .out( mmio_addr )
  );
  assign is_mmio = is_mmio_temp;
endmodule

