  wire bsel;
  wire binv;
  wire csel;
  wire [31:0] FLAG_C32;
  wire [31:0] s0;
  assign FLAG_C32[0] = FLAG_C;
  assign FLAG_C32[31:1] = 31'b1;
  assign \a0-7  = A[7:0];
  assign \a8-15  = A[15:8];
  assign \a16-23  = A[23:16];
  assign \a24-31  = A[31:24];
  assign \b0-7  = B[7:0];
  assign \b8-15  = B[15:8];
  assign \b16-23  = B[23:16];
  assign \b24-31  = B[31:24];
  assign asel = control[0];
  assign ainv = control[1];
  assign bsel = control[2];
  assign binv = control[3];
  assign csel = control[4];
  Mux_2x1_NBits #(
    .Bits(32)
  )
  Mux_2x1_NBits_i0 (
    .sel( \cin-sel  ),
    .in_0( FLAG_C32 ),
    .in_1( 32'b1 ),
    .out( s0 )
  );
  Mux_2x1_NBits #(
    .Bits(32)
  )
  Mux_2x1_NBits_i1 (
    .sel( csel ),
    .in_0( s0 ),
    .in_1( REG_C ),
    .out( ceff )
  );
  assign \c0-7  = ceff[7:0];
  assign \c8-15  = ceff[15:8];
  assign \c16-23  = ceff[23:16];
  assign \c24-31  = ceff[31:24];
  assign cin0 = \c0-7 [0];
  // Cell 0
  alu_8b_final alu_8b_final_i2 (
    .opcode( Opcode ),
    .control( control ),
    .A( \a0-7  ),
    .B( \b0-7  ),
    .C( \c0-7  ),
    .\nz-in ( nz0 ),
    .cin( cin0 ),
    .out( \out0-7  ),
    .\nz-out ( nz1 ),
    .cout( c7 )
  );
  // Cell 2
  alu_8b_final alu_8b_final_i3 (
    .opcode( Opcode ),
    .control( control ),
    .A( \a16-23  ),
    .B( \b16-23  ),
    .C( \c16-23  ),
    .\nz-in ( nz1 ),
    .cin( c15 ),
    .out( \out16-23  ),
    .\nz-out ( nz2 ),
    .cout( c23 )
  );
  // Cell 1
  alu_8b_final alu_8b_final_i4 (
    .opcode( Opcode ),
    .control( control ),
    .A( \a8-15  ),
    .B( \b8-15  ),
    .C( \c8-15  ),
    .\nz-in ( nz2 ),
    .cin( c7 ),
    .out( \out8-15  ),
    .\nz-out ( nz3 ),
    .cout( c15 )
  );
  // Cell 3
  alu_8b_final alu_8b_final_i5 (
    .opcode( Opcode ),
    .control( control ),
    .A( \a24-31  ),
    .B( \b24-31  ),
    .C( \c24-31  ),
    .\nz-in ( nz3 ),
    .cin( c23 ),
    .out( \out24-31  ),
    .vout( vout ),
    .\nz-out ( nzout_temp ),
    .n( nout ),
    .cout( cout )
  );
  assign Out[7:0] = \out0-7 ;
  assign Out[15:8] = \out8-15 ;
  assign Out[23:16] = \out16-23 ;
  assign Out[31:24] = \out24-31 ;
  assign zout = ~ nzout_temp;
  assign nzout = nzout_temp;
endmodule

module main (
  input clk,
  input reset,
  output [23:0] b,
  output [31:0] a,
  output [31:0] f,
  output [23:0] e,
  output [23:0] i,
  output [7:0] h,
  output [7:0] d,
  output [7:0] g,
  output [7:0] c,
  output [7:0] k,
  output [31:0] j,
  output [31:0] l,
  output [31:0] m,
  output [31:0] p,
  output [15:0] term_data,
  output [15:0] vram_addr,
  output term_we,
  output [31:0] r,
  output [31:0] n,
  output a1,
  output [7:0] a2,
  output [7:0] a3,
  output [23:0] t8
);
  wire [1:0] ctrl_cycles;
  wire seq_fetch;
  wire seq_exec;
  wire [23:0] i_temp;
  wire [23:0] e_temp;
  wire [23:0] t8_temp;
  wire \pc-mux-sel-1 ;
  wire \pc-mux-sel-2 ;
  wire flag_n;
  wire flag_c;
  wire flag_z;
  wire flag_v;
  wire [2:0] cond;
  wire \pc-branch-en ;
  wire HALT_IN;
  wire [23:0] sp_delta;
  wire sp_load_n;
  wire \pc-jump-uncond ;
  wire [23:0] b_temp;
  wire [31:0] l_temp;
  wire [31:0] f_temp;
  wire [7:0] a3_temp;
  wire [7:0] d_temp;
  wire [7:0] a2_temp;
  wire [7:0] c_temp;
  wire [7:0] k_temp;
  wire [4:0] ctrl_alu_pre;
  wire ctrl_cin_sel;
  wire [2:0] ctrl_wb_sel;
  wire [1:0] ctrl_shift_op;
  wire ctrl_flags_we;
  wire a1_temp;
  wire ctrl_mem_rd;
  wire ctrl_mem_wr;
  wire ctrl_addr_csel;
  wire ctrl_branch_en;
  wire ctrl_jump_type;
  wire [1:0] ctrl_sp_op;
  wire [2:0] ctrl_bus_sel;
  wire [2:0] \b-main-sel ;
  wire [31:0] m_temp;
  wire [31:0] n_temp;
  wire [31:0] r_temp;
  wire [31:0] reg_c;
  wire [31:0] alu_b;
  wire alu_vout;
  wire alu_zout;
  wire alu_nzout;
  wire alu_nout;
  wire [31:0] j_temp;
  wire alu_cout;
  wire [31:0] shift_out;
  wire [31:0] io_data_in;
  wire s0;
  wire s1;
  wire [23:0] mem_addr;
  wire [23:0] CPU_ADDR_OUT;
  wire [23:0] mmio_addr;
  wire is_mmio;
  wire ram_cs;
  wire vram_we;
  wire [15:0] vram_data;
  wire mem_rd_out;
  wire s2;
  wire [23:0] mem_addr_in;
  wire s3;
  wire [7:0] \ir-24-31 ;
  wire [31:0] \mem-eeprom-out ;
  sequencer sequencer_i0 (
    .reset( reset ),
    .cycles( ctrl_cycles ),
    .CLK( clk ),
    .FETCH( seq_fetch ),
    .EXECUTE( seq_exec )
  );
  pc pc_i1 (
    .CLK( clk ),
    .\~SR ( reset ),
    .ADDR_ABS( i_temp ),
    .OFFSET( e_temp ),
    .ADDR_RET( t8_temp ),
    .MUX1_SEL( \pc-mux-sel-1  ),
    .MUX2_SEL( \pc-mux-sel-2  ),
    .FLAG_N( flag_n ),
    .FLAG_C( flag_c ),
    .FLAG_Z( flag_z ),
    .FLAG_O( flag_v ),
    .COND( cond ),
    .BRANCH_EN( \pc-branch-en  ),
    .INT_EN_IN( 1'b0 ),
    .HALT_IN( HALT_IN ),
    .INT_REQ( 1'b0 ),
    .INT_VEC_0( 1'b1 ),
    .INT_VEC_1( 1'b1 ),
    .INT_VEC_2( 1'b1 ),
    .SP_DELTA( sp_delta ),
    .SP_LOAD_N( sp_load_n ),
    .JUMP_UNCOND( \pc-jump-uncond  ),
    .PCEN( seq_fetch ),
    .PC_OUT( b_temp ),
    .PC_SAVE( t8_temp )
  );
  register register_i2 (
    .WE( a1_temp ),
    .DATA_W( m_temp ),
    .ADDR_A( a2_temp ),
    .ADDR_B( d_temp ),
    .ADDR_W( a3_temp ),
    .EXEC( seq_exec ),
    .addr_c_sel( ctrl_addr_csel ),
    .ir_bus( f_temp ),
    .clk( clk ),
    .DATA_A( n_temp ),
    .DATA_B( r_temp ),
    .DATA_C( reg_c )
  );
  flag_reg flag_reg_i3 (
    .ZERO_IN( alu_zout ),
    .CARRY_IN( alu_cout ),
    .NEGATIVE_IN( alu_nout ),
    .OVERFLOW_IN( alu_vout ),
    .FLAG_WE( ctrl_flags_we ),
    .CLK( clk ),
    .EXEC( seq_exec ),
    .FLAG_Z( flag_z ),
    .FLAG_C( flag_c ),
    .FLAG_N( flag_n ),
    .FLAG_O( flag_v )
  );
  wb_mux wb_mux_i4 (
    .wb_sel( ctrl_wb_sel ),
    .alu_out( j_temp ),
    .shift_out( shift_out ),
    .pc_save( t8_temp ),
    .mem_din( l_temp ),
    .io_datain( io_data_in ),
    .reg_a( n_temp ),
    .\ir-bus ( f_temp ),
    .reg_w_data( m_temp )
  );
  assign s0 = (seq_exec & a1_temp & s1);
  assign HALT_IN = (s3 & seq_exec);
  assign \pc-branch-en  = (ctrl_branch_en & seq_exec);
  assign \pc-jump-uncond  = (ctrl_jump_type & seq_exec);
  ir ir_i5 (
    .DATA_IN( l_temp ),
    .LOAD( seq_fetch ),
    .CLK( clk ),
    .IR_BUS( f_temp ),
    .OPCODE( c_temp ),
    .ADDR_A( a2_temp ),
    .ADDR_B( d_temp ),
    .ADDR_W( a3_temp ),
    .ADDR_ABS( i_temp ),
    .OFFSET( e_temp ),
    .COND( cond )
  );
  bus_arbitration bus_arbitration_i6 (
    .FETCH( seq_fetch ),
    .PC_OUT( b_temp ),
    .IR_ADDR( i_temp ),
    .Reg_A( j_temp ),
    .MEM_RD_IN( ctrl_mem_rd ),
    .addr_sel( ctrl_bus_sel ),
    .Reg_b( 32'b1 ),
    .\Reg-A-off ( 32'b1 ),
    .\Reg-B-off ( 32'b1 ),
    .\Reg-AB ( 32'b1 ),
    .\PC-offset ( 32'b1 ),
    .\SP-out ( 32'b1 ),
    .\Alu-in ( 32'b1 ),
    .ADDR_BUS( mem_addr ),
    .MEM_RD_OUT( mem_rd_out )
  );
  microcode microcode_i7 (
    .op( c_temp ),
    .\alu-op ( k_temp ),
    .\alu-pre ( ctrl_alu_pre ),
    .\cin-sel ( ctrl_cin_sel ),
    .\wb-sel ( ctrl_wb_sel ),
    .\shift-op ( ctrl_shift_op ),
    .\flags-we ( ctrl_flags_we ),
    .\reg-we ( a1_temp ),
    .\mem-rd ( ctrl_mem_rd ),
    .\mem-wr ( ctrl_mem_wr ),
    .\addr-csel ( ctrl_addr_csel ),
    .\branch-en ( ctrl_branch_en ),
    .\jump-type ( ctrl_jump_type ),
    .\sp-op ( ctrl_sp_op ),
    .cycles( ctrl_cycles ),
    .ctrl_bus_sel( ctrl_bus_sel ),
    .\b-main-sel ( \b-main-sel  ),
    .\pc-rel ( \pc-mux-sel-1  )
  );
  CompUnsigned #(
    .Bits(8)
  )
  CompUnsigned_i8 (
    .a( 8'b10 ),
    .b( a3_temp ),
    .\= ( s1 )
  );
  mmio_bus mmio_bus_i9 (
    .ADDR( mem_addr ),
    .CPU_ADDR_OUT( CPU_ADDR_OUT ),
    .mmio_addr( mmio_addr ),
    .is_mmio( is_mmio )
  );
  CompUnsigned #(
    .Bits(8)
  )
  CompUnsigned_i10 (
    .a( 8'b11111111 ),
    .b( c_temp ),
    .\= ( s3 )
  );
  assign \ir-24-31  = f_temp[31:24];
  shift shift_i11 (
    .A( n_temp ),
    .mode( ctrl_shift_op ),
    .B( r_temp ),
    .Out( shift_out )
  );
  io_controller io_controller_i12 (
    .mem_addr( mmio_addr ),
    .c_wr( ctrl_mem_wr ),
    .kb_data( 16'b1 ),
    .mem_data_out( r_temp ),
    .io_data_in( io_data_in ),
    .ram_cs( ram_cs ),
    .vram_we( vram_we ),
    .vram_addr( vram_addr ),
    .vram_data( vram_data ),
    .term_we( term_we ),
    .term_data( term_data )
  );
  assign s2 = (is_mmio & mem_rd_out);
  CompUnsigned #(
    .Bits(8)
  )
  CompUnsigned_i13 (
    .a( \ir-24-31  ),
    .b( 8'b110011 ),
    .\= ( \pc-mux-sel-2  )
  );
  Mux_4x1_NBits #(
    .Bits(24)
  )
  Mux_4x1_NBits_i14 (
    .sel( ctrl_sp_op ),
    .in_0( 24'b0 ),
    .in_1( 24'b1 ),
    .in_2( 24'b111111111111111111111111 ),
    .in_3( 24'b0 ),
    .out( sp_delta )
  );
  assign sp_load_n = ~ (ctrl_sp_op[0] | ctrl_sp_op[1]);
  b_mux b_mux_i15 (
    .ir( f_temp ),
    .reg_b( r_temp ),
    .sel( \b-main-sel  ),
    .\alu-b ( alu_b )
  );
  DIG_RAMDualPort #(
    .Bits(32),
    .AddrBits(24)
  )
  DIG_RAMDualPort_i16 (
    .A( mem_addr ),
    .Din( r_temp ),
    .str( ctrl_mem_wr ),
    .C( clk ),
    .ld( mem_rd_out ),
    .D( \mem-eeprom-out  )
  );
  alu_32b_final alu_32b_final_i17 (
    .A( n_temp ),
    .nz0( 1'b0 ),
    .B( alu_b ),
    .Opcode( k_temp ),
    .control( ctrl_alu_pre ),
    .REG_C( reg_c ),
    .\cin-sel ( ctrl_cin_sel ),
    .FLAG_C( flag_c ),
    .vout( alu_vout ),
    .zout( alu_zout ),
    .nzout( alu_nzout ),
    .nout( alu_nout ),
    .Out( j_temp ),
    .cout( alu_cout )
  );
  DIG_Register_BUS #(
    .Bits(32)
  )
  DIG_Register_BUS_i18 (
    .D( alu_b ),
    .C( clk ),
    .en( s0 ),
    .Q( p )
  );
  Mux_2x1_NBits #(
    .Bits(24)
  )
  Mux_2x1_NBits_i19 (
    .sel( s2 ),
    .in_0( CPU_ADDR_OUT ),
    .in_1( mmio_addr ),
    .out( mem_addr_in )
  );
  Mux_2x1_NBits #(
    .Bits(32)
  )
  Mux_2x1_NBits_i20 (
    .sel( ram_cs ),
    .in_0( \mem-eeprom-out  ),
    .in_1( io_data_in ),
    .out( l_temp )
  );
  assign b = b_temp;
  assign a = l_temp;
  assign f = f_temp;
  assign e = e_temp;
  assign i = i_temp;
  assign h = a3_temp;
  assign d = d_temp;
  assign g = a2_temp;
  assign c = c_temp;
  assign k = k_temp;
  assign j = j_temp;
  assign l = l_temp;
  assign m = m_temp;
  assign r = r_temp;
  assign n = n_temp;
  assign a1 = a1_temp;
  assign a2 = a2_temp;
  assign a3 = a3_temp;
  assign t8 = t8_temp;
endmodule
